const root = $json.body ?? $json;
const data = root.data ?? root;
const transcript = data.transcript ?? data.conversation?.transcript ?? [];
let transcriptText = '';
if (Array.isArray(transcript)) {
  transcriptText = transcript.map((turn) => {
    const role = turn.role ?? turn.speaker ?? 'speaker';
    const text = turn.message ?? turn.text ?? turn.content ?? '';
    return text ? role + ': ' + text : '';
  }).filter(Boolean).join('\n');
} else if (typeof transcript === 'string') { transcriptText = transcript; }
const analysis = data.analysis ?? {};
const summary = analysis.transcript_summary ?? analysis.call_summary ?? data.summary ?? '';
const caller = data.caller_name ?? data.dynamic_variables?.caller_name ?? 'Unknown caller';
const conversationId = data.conversation_id ?? root.conversation_id ?? 'unknown';
const eventType = root.type ?? root.event_type ?? 'post_call';
return [{ json: { received: true, event_type: eventType, conversation_id: conversationId, caller_name: caller, summary: summary || 'No generated summary was found; review the transcript.', transcript: transcriptText, raw_analysis: analysis, received_at: new Date().toISOString() } }];
